import type { NoteRow } from "../drivers/postgres/schema";

export class Note {
  private constructor(
    readonly id: string,
    readonly title: string,
  ) {}

  static fromRow(row: NoteRow): Note {
    return new Note(row.id, row.title);
  }
}

