// use-cases/list-notes.ts
import type { Note } from "../entities/note";
import type { NoteRepository } from "./ports";

export class ListNotes {
  constructor(private readonly notes: NoteRepository) {}

  async execute(ownerId: string): Promise<Response> {
    const found: Note[] = await this.notes.findByOwner(ownerId);
    return Response.json(found, { status: 200 });
  }
}

